    "tx_power_dbm": 7,
    "obss_pd_dbm": -75
  },
  "AP2": {
    "tx_power_dbm": 7,
    "obss_pd_dbm": -75
  },
  "AP3": {
    "tx_power_dbm": 7,
    "obss_pd_dbm": -75
  },
  "_sr": {
    "concurrent_group": ["ap1", "ap3"],
    "non_concurrent_aps": ["ap2"]
  }
}
```

